#include <stdio.h>

int main(void)
{
    int n = 0;
    unsigned long long result = 1;
    for (int i = 2; i <= n; i++) {
        result *= (unsigned long long)i;
    }
    printf("%llu\n", result);
    return 0;
}

#include <stdio.h>

int main(void)
{
    int a = 18, b = 12;
    int x = a;
    int y = b;
    while (y != 0) {
        int remainder = x % y;
        x = y;
        y = remainder;
    }
    long long lcm = 0;
    if (x != 0) {
        lcm = (long long)(a / x) * b;
    }
    printf("%d %lld\n", x, lcm);
    return 0;
}

#include <stdio.h>

int main(void)
{
    int n = 1;
    int sum = 0;
    for (int divisor = 1; divisor <= n / 2; divisor++) {
        if (n % divisor == 0) {
            sum += divisor;
        }
    }
    printf("%d\n", n > 1 && sum == n);
    return 0;
}

